insert into public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit_code, base_quantity, base_unit_code, display_order)
select distinct on (recipes.id, ingredients.id) recipes.id, ingredients.id, source.quantity, ingredients.default_unit_code, source.quantity, ingredients.default_unit_code, source.display_order
from catalog join public.recipes recipes on recipes.slug = catalog.slug and recipes.source_type = 'system'
cross join lateral (values (catalog.primary_ingredient_slug, 300::numeric, 1), (catalog.secondary_ingredient_slug, 160::numeric, 2), ('onion'::text, 100::numeric, 3), ('tomato'::text, 120::numeric, 4), ('salt'::text, 8::numeric, 5)) as source(ingredient_slug, quantity, display_order)
join public.ingredients ingredients on ingredients.slug = source.ingredient_slug
where not exists (
  select 1 from public.recipe_ingredients existing
  where existing.recipe_id = recipes.id and existing.ingredient_id = ingredients.id
)
order by recipes.id, ingredients.id, source.display_order;

