insert into public.recipe_steps (recipe_id, step_number, instruction, tip, estimated_duration_minutes)
select recipes.id, steps.step_number, steps.instruction, steps.tip, steps.duration
from catalog join public.recipes recipes on recipes.slug = catalog.slug and recipes.source_type = 'system'
cross join lateral (values
  (1::smallint, 'Prepare the ingredients for ' || catalog.name || ': rinse, chop and measure everything before heating the pan.', 'Keeping the ingredients ready makes a home-style recipe calm and easy to manage.', 10),
  (2::smallint, case when catalog.region = 'South Indian' then 'Heat oil, temper mustard or cumin with curry leaves, then cook the aromatics and main ingredients over medium heat until fragrant and tender.' when catalog.region = 'North Indian' then 'Cook onion, tomato and warming spices until the masala is glossy, then add the main ingredients and simmer until tender.' else 'Cook the main ingredients in a hot pan with simple spices, stirring until evenly cooked and well combined.' end, 'Use medium heat and add a splash of hot water only if the pan starts to catch.', 18),
  (3::smallint, 'Taste, adjust salt and finish ' || catalog.name || ' with coriander, lemon or a small spoon of ghee before serving warm.', 'Let the dish rest for two minutes so the flavours settle before serving.', 4)
) as steps(step_number, instruction, tip, duration)
on conflict (recipe_id, step_number) do nothing;

select public.recalculate_recipe_quality(id), public.recalculate_recipe_estimated_cost(id)
from public.recipes where source_type = 'system' and slug in (select slug from public.recipes where source_type = 'system');
